const art = {"ponies": ["data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,"]}
const names = ['Fluttershy','Applejack','Twilight Sparkle','Pinkie Pie','Rarity','Rainbow Dash']
const panel = document.querySelector('#panel')
const posterMarkup = panel.innerHTML
const games = ['trail', 'choose', 'dress']
let lastRandomGame
let screen, mode, pony=2, timers=[], idle, audio
const after=(ms,fn)=>{const id=setTimeout(fn,ms);timers.push(id);return id}
const IDLE_TIMEOUT = 15000
function resetIdle(){clearTimeout(idle);if(screen!=='wait')idle=setTimeout(wait,IDLE_TIMEOUT)}
function setScreen(name,html){
  timers.forEach(clearTimeout);timers=[];screen=name
  panel.className=name
  panel.innerHTML=(name==='wait'?'':'<button class="home kioskHome" data-action="home" aria-label="Voltar ao início">'+avatarIcon('home')+'</button>')+html
  resetIdle()
}
const header=(title,sub='')=>'<header class="head"><h1>'+title+'</h1>'+(sub?'<p>'+sub+'</p>':'')+'</header>'
const img=(id,cls='')=>'<img draggable="false" class="'+cls+'" src="'+art.ponies[id]+'" alt="'+names[id]+'">'
const bar=(cls,label)=>'<div class="meter '+cls+'" role="progressbar" aria-label="'+label+'" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><i></i></div>'
function progress(el,value){el.setAttribute('aria-valuenow',Math.round(value));el.firstElementChild.style.width=value+'%'}
function wait(){
  setScreen('wait',posterMarkup)
}
function begin(game){
  mode=game
  if(game==='trail'){pony=5;trail()}
  if(game==='choose')choose()
  if(game==='dress'){pony=2;dress()}
}
const frameCount=18
const poseNames=['Pinkie Pie','Apple Bloom','Celestia','Bon Bon','Trixie','Rarity','Applejack','Derpy','Luna','Fluttershy','Lyra','Rainbow Dash','Twilight Sparkle','Shining Armor','Zecora','Roseluck','Scootaloo','Big Mac']
let currentPose=0
const posePosition=frame=>(frame%6)*20+'% '+Math.floor(frame/6)*50+'%'
function pose(frame){
  return '<div class="pose" role="img" aria-label="'+poseNames[frame]+'" style="background-position:'+posePosition(frame)+'"></div>'
}
function choose(){
  currentPose=Math.floor(Math.random()*frameCount)
  setScreen('pose-game pose-roll',pose(currentPose)+
    '<button class="poseStop" data-action="pose-stop" aria-label="Toque na estrela para sortear uma pose"><span aria-hidden="true"></span></button>')
  const tile=panel.querySelector('.pose')
  const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches
  function spin(){
    currentPose=(currentPose+1+Math.floor(Math.random()*(frameCount-1)))%frameCount
    tile.style.backgroundPosition=posePosition(currentPose)
    tile.setAttribute('aria-label',poseNames[currentPose])
    after(155,spin)
  }
  if(!reduced)after(155,spin)
}
function imitatePose(){
  const frame=currentPose
  setScreen('pose-game pose-imitate',pose(frame)+
    '<div class="poseDock poseCountdown" role="img" aria-label="Imite a pose do pônei">'+
    '<div class="poseBubbles" aria-hidden="true"><i class="lit">✦</i><i>✦</i><i>✦</i></div></div>')
  const bubbles=panel.querySelectorAll('.poseBubbles i')
  playNotes([523])
  after(1000,()=>{bubbles[1].classList.add('lit');playNotes([659])})
  after(2000,()=>{bubbles[2].classList.add('lit');playNotes([784])})
  after(3000,()=>celebrate(frame))
}
function confetti(){
  return '<div class="confetti" aria-hidden="true">'+Array.from({length:36},(_,i)=>'<b style="left:'+(i*37%101)+'%;background:'+['#f47dbb','#9167eb','#54d4f6','#f5ca42','#76d6a7'][i%5]+';--delay:'+(i%11)*.19+'s;--time:'+(2+i%5*.4)+'s;--drift:'+((i%7-3)*6)+'cqw"></b>').join('')+'</div>'
}
function playNotes(notes){
  if(!audio||audio.state!=='running')return
  const start=audio.currentTime
  notes.forEach((frequency,i)=>{
    const osc=audio.createOscillator(), gain=audio.createGain(), t=start+i*.15
    osc.type='sine';osc.frequency.value=frequency;gain.gain.setValueAtTime(.001,t)
    gain.gain.exponentialRampToValueAtTime(.12,t+.035);gain.gain.exponentialRampToValueAtTime(.001,t+.24)
    osc.connect(gain);gain.connect(audio.destination);osc.start(t);osc.stop(t+.25)
  })
}
const mazeRoute=[
  [132,1453],[210,1414],[454,1414],[459,1267],[459,1161],[95,1161],
  [95,1023],[275,1023],[275,809],[423,809],[423,639],[553,639],
  [553,456],[486,456],[486,335]
]
function roundedMazePath(){
  const blend=(point,other,amount)=>{
    const fraction=Math.min(.35,amount/Math.hypot(other[0]-point[0],other[1]-point[1]))
    return [point[0]+(other[0]-point[0])*fraction,point[1]+(other[1]-point[1])*fraction].join(' ')
  }
  let path='M'+mazeRoute[0].join(' ')
  for(let i=1;i<mazeRoute.length-1;i++){
    const point=mazeRoute[i]
    path+=' L'+blend(point,mazeRoute[i-1],26)+' Q'+point.join(' ')+' '+blend(point,mazeRoute[i+1],26)
  }
  return path+' L'+mazeRoute.at(-1).join(' ')
}
function trail(){
  const rainbow=['#ff83b5','#ffbc91','#ffe59b','#a4ecc7','#8fdfff','#baa5f6']
  setScreen('trail',
    '<svg class="mazeBoard" viewBox="0 0 941 1672" aria-label="Guie a Rainbow Dash pelo labirinto de nuvens até o arco-íris">'+
    '<defs><linearGradient id="mazeRainbow" x2="0" y2="1">'+rainbow.map((c,i)=>'<stop offset="'+i*20+'%" stop-color="'+c+'"/>').join('')+'</linearGradient></defs>'+
    '<path class="mazeVisited" d="'+roundedMazePath()+'" fill="none" stroke="url(#mazeRainbow)" stroke-width="22" stroke-linecap="round"/>'+
    '<circle class="mazeStart" cx="132" cy="1453" r="34"/>'+
    '<g class="mazePony" transform="translate(132 1453)"><ellipse rx="39" ry="12" fill="#ae8ad2" opacity=".27"/>'+
    '<image href="'+art.ponies[5]+'" x="-65" y="-158" width="130" height="158"/></g>'+
    '</svg><div class="mazeMeter">'+bar('','Progresso no labirinto')+'</div>')
  const svg=panel.querySelector('.mazeBoard')
  const ponyMarker=svg.querySelector('.mazePony')
  const ink=svg.querySelector('.mazeVisited')
  const start=svg.querySelector('.mazeStart')
  const meter=panel.querySelector('.meter')
  const length=ink.getTotalLength()
  const count=Math.ceil(length/5)
  const points=Array.from({length:count+1},(_,i)=>ink.getPointAtLength(i*length/count))
  const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches
  const distance=(p,q)=>Math.hypot(p.x-q.x,p.y-q.y)
  const point=e=>new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse())
  let target=0,shown=0,pointer=null,last=null,frame=null,previousTime=null
  ink.style.strokeDasharray=length+' '+length
  ink.style.strokeDashoffset=length
  function draw(now){
    frame=null
    if(!svg.isConnected)return
    const elapsed=previousTime===null?16:Math.min(50,now-previousTime)
    previousTime=now
    const delta=target-shown
    shown=delta<.45||reduced?target:shown+delta*(1-Math.exp(-elapsed/42))
    const travelled=shown*length/count
    const p=ink.getPointAtLength(travelled)
    ponyMarker.setAttribute('transform','translate('+p.x+' '+p.y+')')
    ink.style.strokeDashoffset=length-travelled
    progress(meter,100*shown/count)
    if(shown===count){celebrate();return}
    if(shown<target)schedule()
    else previousTime=null
  }
  function schedule(){
    if(frame===null)frame=requestAnimationFrame(draw)
  }
  function guideFinger(p){
    let best=target
    let gap=Math.min(64,distance(p,points[target]))
    // Only look ahead locally so a nearby corridor can't skip a turn.
    for(let i=target+1;i<=Math.min(count,target+14);i++){
      const candidate=distance(p,points[i])
      if(candidate<gap){best=i;gap=candidate}
    }
    if(best!==target){
      target=best>=count-2?count:best
      schedule()
    }
  }
  svg.addEventListener('pointerdown',e=>{
    if(pointer!==null||!e.isPrimary||target===count)return
    const p=point(e)
    const position=ink.getPointAtLength(shown*length/count)
    if(distance(p,position)>76&&distance(p,{x:position.x,y:position.y-76})>78)return
    pointer=e.pointerId;last=p;svg.setPointerCapture(pointer);start.classList.add('playing')
  })
  svg.addEventListener('pointermove',e=>{
    if(e.pointerId!==pointer||target===count)return
    const p=point(e)
    const steps=Math.max(1,Math.ceil(distance(p,last)/12))
    for(let i=1;i<=steps;i++)guideFinger({x:last.x+(p.x-last.x)*i/steps,y:last.y+(p.y-last.y)*i/steps})
    last=p
  })
  for(const event of ['pointerup','pointercancel','lostpointercapture'])svg.addEventListener(event,e=>{
    if(e.pointerId===pointer){pointer=null;last=null}
  })
}
const palette=[['Branco','#fffaf6'],['Rosa','#f5a8d4'],['Lilás','#c8b4fa'],['Azul','#92d7fa'],['Menta','#9de4c5'],['Amarelo','#ffe28a'],['Pêssego','#ffb99a']]
