const hairExtensions=[
  '',
  'M567 482Q559 570 610 623Q649 674 603 742Q579 777 530 792Q550 761 547 729Q541 702 516 683Q470 642 470 584Q467 519 502 483Z',
  'M565 471Q597 497 575 529Q623 521 631 562Q638 598 599 610Q638 625 621 661Q606 687 568 676Q552 718 513 699Q484 687 500 657Q455 651 461 613Q465 589 490 582Q461 552 478 525Q489 506 515 510Z'
]
function avatarArt(model=avatar,scope="main"){
  const regions=Object.entries(avatarRegions)
  const color=key=>palette[model[key]][1]
  const filters=regions.map(([key,path])=>{
    const hex=color(key)
    const slopes=[1,3,5].map(offset=>parseInt(hex.slice(offset,offset+2),16)/255)
    return '<clipPath id="avatar-'+scope+'-'+key+'"><path clip-rule="evenodd" d="'+path+'"/></clipPath>'+
      '<filter id="tint-'+scope+'-'+key+'" color-interpolation-filters="sRGB"><feComponentTransfer>'+
      ['R','G','B'].map((channel,index)=>'<feFunc'+channel+' type="linear" slope="'+slopes[index]+'"/>').join('')+
      '</feComponentTransfer></filter>'
  }).join('')
  const overlays=regions.filter(([key])=>model[key]!==0).map(([key])=>
    '<g clip-path="url(#avatar-'+scope+'-'+key+')"><use href="#avatar-raster-'+scope+'" filter="url(#tint-'+scope+'-'+key+')"/></g>').join('')
  const mark=model.mark===0?'<path d="m704 665 12 24 27 4-20 20 5 28-24-13-25 13 5-28-20-20 27-4Z" fill="#f4b633"/>':
    model.mark===1?'<path d="M704 738Q646 703 670 676Q688 662 704 685Q722 662 740 676Q765 703 704 738Z" fill="#ee7db6"/>':''
  const extension=model.cut?'<path d="'+hairExtensions[model.cut]+'" fill="'+color('mane')+'" stroke="#835890" stroke-width="11" stroke-linejoin="round"/>'+
    '<path d="'+(model.cut===1?'M513 603Q521 671 568 694Q586 720 566 751':'M555 562Q606 553 586 583Q571 603 549 594M524 621Q499 635 525 648')+'" fill="none" stroke="#835890" stroke-width="8" stroke-linecap="round" opacity=".45"/>':''
  return '<svg viewBox="0 0 1312 1199" role="img" aria-label="Seu pônei de perfil"><defs>'+
    '<image id="avatar-raster-'+scope+'" href="avatar-base.webp" width="1312" height="1199"/>'+filters+'</defs>'+
    '<use href="#avatar-raster-'+scope+'"/>'+overlays+extension+
    '<g stroke="#fff" stroke-width="7" stroke-linejoin="round">'+mark+'</g></svg>'
}

