    mane:'<path d="M10 19q17-12 36-7 12 4 10 16-4 16-23 23 6-9 4-17-9 13-21 15 5-10 1-14l-8 3q3-9 1-19Z" fill="#acdafa"/>',
    mark:'<path d="m32 8 7 14 16 3-11 11 2 16-14-7-14 7 2-16L9 25l16-3Z" fill="#ffdb86" stroke="#dfa35f"/>',
