function dress(){
  avatar={body:0,tail:0,cut:0,mane:0,mark:2}
  avatarStep=0
  setScreen('dress',
    '<div class="avatarRibbon" aria-hidden="true"></div>'+
    '<div class="avatarTimer">'+avatarIcon('clock')+bar('','Tempo restante')+'</div>'+
    '<div class="avatarLayout"><div class="avatarPreview"></div><div class="avatarChoices"></div></div>'+
    '<div class="avatarBottom"><button class="pill visualControl" data-action="avatar-next" aria-label="Próxima etapa"></button></div>')
  renderAvatarStep()
  const timer=panel.querySelector('.avatarTimer')
  const deadline=performance.now()+60000
  const meter=timer.querySelector('.meter')
  progress(meter,100)
  function tick(now){
    if(!timer.isConnected)return
    const remaining=Math.max(0,deadline-now)
    progress(meter,remaining/600)
    requestAnimationFrame(tick)
  }
  requestAnimationFrame(tick)
  after(60000,celebrate)
}
function renderAvatarStep(){
  const step=avatarSteps[avatarStep]
  const options=step.colors?palette.map(([name])=>name):step.options
  panel.querySelector('.avatarPreview').innerHTML=avatarArt()
  panel.querySelector('.avatarRibbon').innerHTML=avatarSteps.map((item,index)=>
    '<span class="'+(index===avatarStep?'current':'')+'">'+avatarIcon(item.key)+'</span>').join('')
  panel.querySelector('.avatarChoices').innerHTML=
    '<div class="avatarCategory" role="img" aria-label="'+step.label+'">'+avatarIcon(step.key)+'</div>'+
    '<div class="avatarOptions'+(step.colors?' swatches':'')+'">'+
    options.map((label,index)=>'<button aria-label="'+label+'" data-avatar-option="'+index+'" aria-pressed="'+(avatar[step.key]===index)+'">'+
      (step.colors?'<i style="--swatch:'+palette[index][1]+'" aria-hidden="true"></i>':
      step.key==='cut'?'<span class="cutTile" aria-hidden="true">'+avatarArt({...avatar,cut:index},'cut-'+index)+'</span>':
      avatarIcon(['star','heart','blank'][index]))+'</button>').join('')+'</div>'
  const next=panel.querySelector('[data-action="avatar-next"]')
  const last=avatarStep===avatarSteps.length-1
  next.setAttribute('aria-label',last?'Finalizar':'Próxima etapa')
  next.innerHTML=avatarIcon(last?'check':'next')
}
function chooseAvatarOption(button){
  const index=Number(button.dataset.avatarOption)
  avatar[avatarSteps[avatarStep].key]=index
  panel.querySelector('.avatarPreview').innerHTML=avatarArt()
  panel.querySelectorAll('[data-avatar-option]').forEach(option=>option.setAttribute('aria-pressed',option===button))
}

function celebrate(poseFrame){
  const isPose=mode==='choose'
  const message='Luz e brilho!'
  const figure=isPose?pose(poseFrame):mode==='dress'?'<div class="finishedAvatar jump">'+avatarArt()+'</div>':img(pony,'hero jump')
  if(isPose){
    setScreen('pose-game pose-win',figure+'<div class="poseShine" aria-hidden="true"><i>✦</i><i>✧</i><i>✦</i><i>✧</i></div>'+confetti())
  }else if(mode==='dress'){
    setScreen('celebrate avatarCelebrate','<div class="rays"></div><div class="avatarSuccess" aria-hidden="true">'+avatarIcon('star')+'</div>'+figure+confetti())
  }else{
    setScreen('celebrate','<div class="rays"></div>'+header(message)+figure+confetti())
  }
  playNotes([659,784,988,1319]);after(7000,wait)
}
function startRandomGame(){
  unlockAudio()
  const choices=games.filter(game=>game!==lastRandomGame)
  lastRandomGame=choices[Math.floor(Math.random()*choices.length)]
  begin(lastRandomGame)
}
panel.addEventListener('pointerdown',e=>{
  if(screen!=='wait'||e.target.closest('button')||!e.isPrimary||(e.pointerType==='mouse'&&e.button!==0))return
  e.preventDefault();startRandomGame()
})
panel.addEventListener('contextmenu',e=>e.preventDefault())
document.addEventListener('keydown',e=>{
  if(screen==='wait'&&(e.key==='Enter'||e.key===' ')&&!e.target.closest('button')){e.preventDefault();startRandomGame()}
})
panel.addEventListener('click',resetIdle,true)
panel.addEventListener('pointerdown',resetIdle,true)
panel.addEventListener('pointerup',resetIdle,true)
panel.addEventListener('pointermove',e=>{if(e.buttons||e.pressure)resetIdle()},true)
panel.addEventListener('keydown',resetIdle,true)
function unlockAudio(){
  if(!audio&&window.AudioContext)audio=new AudioContext()
  if(audio?.state==='suspended')audio.resume().catch(()=>{})
}
panel.addEventListener('click',e=>{
  const button=e.target.closest('button')
  if(!button)return
  unlockAudio()
  const {action}=button.dataset
  if(action==='home'){wait();return}
  if(screen==='dress'&&button.hasAttribute('data-avatar-option'))chooseAvatarOption(button)
  if(action==='avatar-next'){
    if(avatarStep===avatarSteps.length-1)celebrate()
    else{avatarStep++;renderAvatarStep()}
  }
  if(action==='pose-stop'&&screen==='pose-game pose-roll')imitatePose()
})
screen='wait'
